package com.railreserve.model;
public final class Seat { private final long id, journeyId; private final TravelClass travelClass; private final String coach; private final int number, fare; private final SeatStatus status; public Seat(long id,long journeyId,TravelClass c,String coach,int number,int fare,SeatStatus status){this.id=id;this.journeyId=journeyId;this.travelClass=c;this.coach=coach;this.number=number;this.fare=fare;this.status=status;} public long getId(){return id;} public long getJourneyId(){return journeyId;} public TravelClass getTravelClass(){return travelClass;} public String getCoach(){return coach;} public int getNumber(){return number;} public int getFare(){return fare;} public SeatStatus getStatus(){return status;} }
